function minimumCost(target, words, costs) {
  // Dijkstra over prefix lengths: node p means the first p letters of target are built; a word that matches at p is an edge.
  const n = target.length;
  const dist = new Array(n + 1).fill(Infinity);
  const settled = new Array(n + 1).fill(false);
  dist[0] = 0;
  for (;;) {
    let p = -1;
    for (let q = 0; q <= n; q++) if (!settled[q] && dist[q] < Infinity && (p === -1 || dist[q] < dist[p])) p = q;
    if (p === -1) return -1;
    if (p === n) return dist[n];
    settled[p] = true;
    for (let w = 0; w < words.length; w++) {
      const q = p + words[w].length;
      if (q <= n && target.slice(p, q) === words[w]) dist[q] = Math.min(dist[q], dist[p] + costs[w]);
    }
  }
}

