function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const letters = 'abc'.slice(0, pick(1, 3));
  const randomWord = length => Array.from({ length }, () => letters[pick(0, letters.length - 1)]).join('');
  const target = randomWord(large ? pick(1800, 2000) : pick(1, 8));
  const count = large ? pick(40, 50) : pick(1, 5);
  const longest = Math.min(target.length, large ? (letters.length === 1 ? 60 : 10) : 4);
  const words = [], costs = [];
  while (words.length < count) {
    const length = pick(1, longest);
    const start = pick(0, target.length - length);
    // Most words are pieces of target so that it can usually be built; the rest are random.
    words.push(rand() < (large ? 0.85 : 0.7) ? target.slice(start, start + length) : randomWord(length));
    costs.push(large ? pick(1, 100000) : pick(1, 20));
  }
  return [target, words, costs];
}
